<script lang="ts">
 import type {InvestigationGuide} from './guide.svelte';
 let {guide,onnavigate,onimport}:{guide:InvestigationGuide;onnavigate:(view:'Evidence'|'Entities'|'Graph'|'Export')=>void;onimport:()=>void}=$props();
 let expanded=$state(true);
 let steps=$derived([{title:'Create or open an encrypted case',done:true,action:'Case is open',run:()=>{}},{title:'Import a document and extract supported content',done:Boolean(guide.status&&guide.status.artifacts>0&&guide.status.complete>0),action:'Import evidence',run:onimport},{title:'Inspect an observation and its original source',done:Boolean(guide.events.observation_read&&guide.events.source_read),action:'Open evidence',run:()=>onnavigate('Evidence')},{title:'Create two grounded entities and connect them',done:Boolean(guide.status&&guide.status.entities>=2&&guide.status.relationships>0),action:'Open entities',run:()=>onnavigate('Entities')},{title:'Inspect the relationship in Graph and record a human judgment',done:Boolean(guide.events.graph_relationship_read&&guide.status&&guide.status.human_assessments>0),action:'Open Graph',run:()=>onnavigate('Graph')},{title:'Save a graph board and create a report or package',done:Boolean(guide.status&&guide.status.boards>0&&(guide.status.reports>0||guide.events.package_exported)),action:'Open Export',run:()=>onnavigate('Export')}]);
</script>
{#if !guide.dismissed}<section aria-labelledby="guide-title"><header><h3 id="guide-title">Your first investigation</h3><button type="button" aria-expanded={expanded} onclick={()=>expanded=!expanded}>{expanded?'Collapse guide':'Expand guide'}</button><button type="button" onclick={guide.hide}>I’ll explore on my own</button></header><p>{steps.filter(s=>s.done).length} of 6 steps complete. Use your own evidence; nothing is created automatically.</p>{#if expanded}<ol>{#each steps as step}<li><strong>{step.done?'Complete: ':'Next: '}{step.title}</strong>{#if !step.done}<button type="button" onclick={step.run}>{step.action}</button>{/if}</li>{/each}</ol><p>Import stores original bytes. Extraction creates observations with source locations. Unsupported or partly read files remain visible. Your judgment can disagree with a source; this guide never chooses it.</p><button type="button" onclick={()=>void guide.refresh()}>Refresh guide progress</button>{#if guide.error}<p role="status">Guide progress could not be loaded. Your investigation controls remain available.</p>{/if}{/if}</section>{/if}
